<?php $pageTitle='Academic progression';$labels=['students'=>'Students checked','updates'=>'Placement changes','active'=>'Active placements','held'=>'Held students','awaiting_completion'=>'Awaiting completion','withdrawn'=>'Withdrawn / inactive','completed'=>'Completion confirmed','not_started'=>'Not started','blocked'=>'Missing academic data','missing_curriculum'=>'Missing current curriculum']; ?>
<div class="academic-progression-page">
