<label>Academic session / odd semester starts<input name="session_start" value="<?= e($settings['session_start']) ?>" pattern="\d{2}-\d{2}" placeholder="07-01" required></label>
<label>Even semester starts<input name="even_start" value="<?= e($settings['even_start']) ?>" pattern="\d{2}-\d{2}" placeholder="01-01" required></label>
