<section class="panel form-section"><h2>Preview academic changes</h2><form class="filter-bar" method="get"><label>Preview date<input type="date" name="preview_date" value="<?= e($previewDate) ?>" required></label><button class="secondary-button">Preview only</button></form>
<p>Session <strong><?= e($preview['period']['academic_session']) ?></strong>, <?= $preview['period']['term']===1?'odd':'even' ?> semester. Next transition: <strong><?= e($preview['period']['next_date']) ?></strong>. Future previews do not change records.</p>
<div class="table-scroll"><table><thead><tr><th>Measure</th><th>Students</th></tr></thead><tbody><?php foreach($labels as $key=>$label):?><tr><td><?= e($label) ?></td><td><?= number_format($preview['counts'][$key]) ?></td></tr><?php endforeach;?></tbody></table></div>
<form method="post" action="<?= e(url('academic-rollover/run')) ?>"><?= csrf_field() ?><p>Reconciliation always uses today's date, <?= e(date('Y-m-d')) ?>, regardless of the preview date. Repeated runs do not promote a student twice.</p><button class="primary-button" <?= !$settings['enabled']?'disabled':'' ?>>Reconcile today's placements</button></form></section>
<?php if($mismatchedCycles):?><section class="panel form-section"><h2>Examination sessions to review</h2><p>These draft cycles have an academic year that differs from their start date. Existing cycles have not been changed. Create a correctly dated cycle before generating a new regular schedule.</p><ul><?php foreach($mismatchedCycles as $cycle):?><li><a href="<?= e(url('date-sheets/'.$cycle['id'])) ?>"><?= e($cycle['name']) ?></a>: <?= e($cycle['academic_year']) ?>, starting <?= e($cycle['start_date']) ?><form method="post" action="<?= e(url('academic-rollover/cycles/'.$cycle['id'].'/session')) ?>"><?= csrf_field() ?><button class="secondary-button">Align session if draft is empty</button></form></li><?php endforeach;?></ul></section><?php endif;?>
<section class="panel form-section"><h2>Review filter</h2><form method="get" class="filter-bar"><input type="hidden" name="preview_date" value="<?= e($previewDate) ?>"><label>Show<select name="review"><?php foreach(['all'=>'All changes and exceptions','updates'=>'Placement changes','missing_curriculum'=>'Missing curriculum','blocked'=>'Missing academic data','held'=>'Held students','awaiting_completion'=>'Awaiting completion','withdrawn'=>'Withdrawn','completed'=>'Completion confirmed','active'=>'Active placements'] as $key=>$label):?><option value="<?= $key ?>" <?= $preview['review']===$key?'selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label><button class="secondary-button">Filter review</button></form></section>
<section class="panel table-panel"><div class="table-toolbar"><strong>Changes and exceptions</strong><span><?= number_format($preview['matches']) ?> records; page <?= $preview['page'] ?> of <?= $preview['pages'] ?></span></div><div class="table-scroll"><table><thead><tr><th>Student</th><th>Batch</th><th>Saved placement</th><th>Preview placement</th><th></th></tr></thead><tbody><?php foreach($preview['items'] as $item):$s=$item['student'];$t=$item['target'];?><tr><td><?= e($s['roll_no_original']) ?><small class="cell-note"><?= e($s['name']) ?></small></td><td><?= e($s['batch_label']??'Unassigned') ?></td><td><?= e($s['academic_session']) ?> / Year <?= (int)$s['current_year_of_study'] ?> / Sem <?= (int)$s['semester'] ?></td><td><?php if(isset($t['error'])):?><?= e($t['error']) ?><?php else:?><?= e($t['academic_session']) ?> / Year <?= $t['study_year'] ?> / Sem <?= $t['semester'] ?><small class="cell-note"><?= e(ucwords(str_replace('_',' ',$t['placement_status']))) ?><?= $item['missing_curriculum']?' - Missing curriculum':'' ?></small><?php endif;?></td><td><a href="<?= e(url('academic-rollover/students/'.$s['id'])) ?>">History &amp; exceptions</a></td></tr><?php endforeach;?><?php if(!$preview['items']):?><tr><td colspan="5">No placement changes or exceptions in this preview.</td></tr><?php endif;?></tbody></table></div></section>
<nav class="pagination" aria-label="Academic review pages"><?php if($preview['page']>1):?><a href="?<?= e(http_build_query(['preview_date'=>$previewDate,'review'=>$preview['review'],'page'=>$preview['page']-1])) ?>">Previous</a><?php endif;?><?php if($preview['page']<$preview['pages']):?><a href="?<?= e(http_build_query(['preview_date'=>$previewDate,'review'=>$preview['review'],'page'=>$preview['page']+1])) ?>">Next</a><?php endif;?></nav>
<section class="panel table-panel"><div class="table-toolbar"><strong>Recent runs</strong></div><div class="table-scroll"><table><thead><tr><th>Checked</th><th>Academic session</th><th>Trigger</th><th>Changes</th><th>Review</th></tr></thead><tbody><?php foreach($runs as $run):$stats=json_decode($run['summary'],true)?:[];?><tr><td><?= e($run['created_at']) ?></td><td><?= e($run['academic_session']) ?></td><td><?= e($run['trigger_source']) ?><small class="cell-note"><?= e($run['actor_name']??'System') ?></small></td><td><?= (int)($stats['updated']??0) ?> students; <?= (int)($stats['registrations']??0) ?> registrations</td><td><?= (int)($stats['blocked']??0) ?> blocked; <?= (int)($stats['missing_curriculum']??0) ?> without current curriculum</td></tr><?php endforeach;?></tbody></table></div></section>
</div>
